/* -------------------------------------------------------------------------- */
/*  Status enum                                                               */
/* -------------------------------------------------------------------------- */

export const ChipStatusSchema = z.enum(['open', 'launched', 'done', 'dismissed']);
export type ChipStatus = z.infer<typeof ChipStatusSchema>;

/**
 * Shared status-filter parsing (CLI + route): `undefined` or `'all'` means no
 * filter; a CSV list is validated against ChipStatusSchema; anything invalid
 * comes back as `{ error }` for the caller to report. Note: the "open,launched"
 * DEFAULT applied when the flag/query param is absent stays a CALLER concern —
 * this only parses what was actually passed.
 */
export function parseStatusFilter(
  raw: string | undefined,
): ChipStatus[] | undefined | { error: string } {
  if (raw === undefined || raw === 'all') return undefined;
  const requested = raw.split(',').map((s) => s.trim());
  const invalid = requested.filter((s) => !ChipStatusSchema.options.includes(s as ChipStatus));
  if (invalid.length) return { error: `statut(s) invalide(s) : ${invalid.join(', ')}` };
  return requested as ChipStatus[];
}

/* -------------------------------------------------------------------------- */
/*  Chip                                                                      */
/* -------------------------------------------------------------------------- */

export const ChipProjectSchema = z.object({
  slug: z.string().min(1),
  name: z.string().min(1),
  path: z.string().min(1),
});
export type ChipProject = z.infer<typeof ChipProjectSchema>;

/**
 * D1 (chantier « provenance de session ») — `ChipOrigin` is now a PROJECTION of
 * `AgentOriginSchema`: every AgentOrigin field is available on a chip's origin,
 * but the four fields that a chip predating this schema never carried
 * (`schemaVersion`, `runtime`, `capturedBy`, `capturedAt`) are made optional so
 * a chip already on disk with only the three historical keys (`sessionId`,
 * `cwd`, `source`) still parses. `source` is re-declared narrower than
 * `AgentOriginSchema`'s (no `'http'` — a chip is never created over plain
 * HTTP) to stay compatible with every existing caller's literal type.
 */
export const ChipOriginSchema = AgentOriginSchema.partial({
  schemaVersion: true,
  runtime: true,
  capturedBy: true,
  capturedAt: true,
}).extend({
  /** `mcp` = created remotely via the hub-write MCP tool `chip_create`. */
  source: z.enum(['hook', 'cli', 'ui', 'mcp']),
});
export type ChipOrigin = z.infer<typeof ChipOriginSchema>;

/**
 * Promote a chip's origin predating the chantier « provenance de session »
 * (`capturedBy` absent — every field `ChipOriginSchema.partial()` above
 * makes optional) to a fully-formed `ChipOrigin`. Recensé en LECTURE SEULE
 * sur `data/chips` (production, 2026-09-09) : exactement TWO shapes lack
 * `capturedBy`, both pre-chantier —
 *
 *  - `{ sessionId, cwd, source: 'hook' }` (326 chips) — the PostToolUse
 *    `chip-spawn-post.ts` hook's own write, from BEFORE it carried
 *    `schemaVersion`/`runtime`/`capturedBy`/`capturedAt`. That hook has only
 *    ever run under Claude Code, so this is a genuine RANK-3 ("hook")
 *    capture, not merely inferred — promoted to `runtime: 'claude'`,
 *    `capturedBy: 'hook'`.
 *  - `{ cwd, source: 'cli' | 'mcp' | 'ui' }`, no `sessionId` (34 chips) —
 *    chips created before origin tracking existed at all; no session
 *    evidence survives. Promoted to `runtime: 'unknown'`,
 *    `capturedBy: 'none'` — the faithful reading of "nothing was actually
 *    captured", which stays ranked below `inferred` so a backfill pass
 *    (`chips backfill-origin`) can still genuinely improve it.
 *
 * A no-op (same reference) once `capturedBy` is already set — every chip
 * written by or after the chantier. `createdAt` (the chip's own, NOT
 * `origin.capturedAt`, which these shapes never had) backfills
 * `capturedAt` — the closest faithful timestamp for when this origin was
 * actually captured.
