content.content:
  Dataverse API does not validate expressions. Semantics come from the live
  engine (`tests/fixtures/expressions/`, captured by `expressions:capture`),
  never from memory; a semantic not captured live is marked `unverified` or
  raises `UnsupportedError` instead of guessing. Add a vector and re-capture
  before relying on a new function or edge case.
- `tools/scenarios/`: live proofs (`scenarios:orders`, `scenarios:template`,
  `scenarios:probe`, `scenarios:fleet`, `scenarios:choices`,
  `scenarios:choices-webapi`).
  A Power Apps-triggered flow is tested through its harness
  (`lab_testrequest` row → Run a Child Flow → response stored on the row).
- `solution/PowerPlatformLab/`: the unpacked, normalized, secret-scanned
  source of the lab solution, written only by `bun run solution:snapshot`
  (`tools/solution/`); never edit it by hand.
- `README.md`: getting started and service principal setup.
- `docs/reports/`: HTML reports for Franck (reviewed in Galley). `evidence/`:
  frozen JSON outputs of live scenario runs.
- Patterns to port, read-only: `../my-flows-definitions/scripts/`
  (compilation, validation, `register-flow-web-api.mjs`) and
  `../TempsChantier/tools/dataverse-admin/` (client, plug-ins, traces).

## Power Platform Architect

To design or review an approach, use the `power-platform-architect` skill
(`.agents/skills/` for Codex, identical copy under `.claude/skills/` for
Claude Code) and its read-only reviewers `pp-app-experience`,
`pp-automation`, `pp-data`, and `pp-plugin-review`. They are managed files
from release 0.5.0 (`.power-platform-architect/`): never edit them here.
Upgrade with `bun run architect:sync <version>`, then
`bun run architect:check`.

## Validation and Git

- `bun run validate` (tests + architect check) must PASS before any commit;
  commands that touch the environment are additionally proven by their JSON
  output `verdict: PASS`.
- After any session that changed the environment (deploy, schema, designer
  edit), run `bun run solution:snapshot` and commit
  `solution/PowerPlatformLab/` with that session's work. A secret-scan `FAIL` blocks the snapshot: remove the
  value from the environment, never from the scan.
  `bun run solution:snapshot -- --check` exits 1 when the environment has
  drifted from Git.
- Remote `git@github-perso:franckdjiongo/power-platform-lab.git` (private).
  Work in a `.worktrees/<slug>` worktree; `main` stays the integrated
  version. No AI attribution in commit messages.
----
// Usage: bun run expressions:capture [-- --documents]
// Runs every conformance vector on the real engine, once, and stores the
// engine's answers as goldens in tests/fixtures/expressions/. Offline tests
// then hold the local evaluator to them. Lab environment only.
import { writeFileSync } from "node:fs";
import { labClient, run } from "../../lib/cli.mjs";
import { findFlowId, upsertFlow } from "../../flows/upsert.mjs";
import { buildHarnessFlow } from "../../flows/error-handling/harness.mjs";
import { submitRequest } from "../../scenarios/harness-client.mjs";
import { parseJson, stringifyJson } from "../json.mjs";
import { VECTORS } from "./vectors.mjs";
import { SCENARIOS as PROBE_SCENARIOS } from "../../scenarios/probe-containers.mjs";
import { PROBE_KEY } from "../../flows/error-handling/probe-containers.mjs";
import { CONFORMANCE_FLOW, CONFORMANCE_KEY, buildConformanceFlow, composeName } from "./flow.mjs";

const SOLUTION = "PowerPlatformLab";
// Fixtures are committed: the lab's Dataverse host becomes a placeholder.
export const HOST_PLACEHOLDER = "lab-environment.crm.dynamics.com";
const sanitizer = (config) => (text) => (text == null ? text : text.split(new URL(config.environmentUrl).host).join(HOST_PLACEHOLDER));
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function rawResponse(client, id, deadline) {
  while (Date.now() < deadline) {
    const { data } = await client.get(`lab_testrequests(${id})?$select=lab_state,lab_responsejson`);
    if (data.lab_state && data.lab_state !== "pending") return { state: data.lab_state, text: data.lab_responsejson };
    await sleep(10_000);
  }
  return { state: "timeout", text: null };
}

async function captureVectors(client, timeoutSeconds) {
  const flow = buildConformanceFlow(VECTORS);
  writeFileSync("flows/probes/expression-conformance.json", `${JSON.stringify(flow, null, 2)}\n`);
  await upsertFlow(client, flow, { solution: SOLUTION, activate: true });
  const harness = buildHarnessFlow({ targetKey: CONFORMANCE_KEY, targetWorkflowId: await findFlowId(client, CONFORMANCE_FLOW) });
  writeFileSync("flows/generated/harness-expression-conformance.json", `${JSON.stringify(harness, null, 2)}\n`);
  await upsertFlow(client, harness, { solution: SOLUTION, activate: true });
  const id = await submitRequest(client, { key: CONFORMANCE_KEY, name: `Expression conformance ${new Date().toISOString()}`, requestJson: "{}" });
  const { state, text } = await rawResponse(client, id, Date.now() + timeoutSeconds * 1000);
  if (state !== "done") throw Object.assign(new Error(`harness state ${state}: ${String(text).slice(0, 500)}`), { code: "capture_failed" });
  const byName = new Map(parseJson(text).flat().map((entry) => [entry.name, entry]));
  return VECTORS.map(({ id: vectorId, topic, value }) => {
    const entry = byName.get(composeName(vectorId));
    if (!entry) return { id: vectorId, topic, value, status: "Missing" };
    return {
      id: vectorId, topic, value, status: entry.status,
      ...(entry.status === "Succeeded" ? { outputs: stringifyJson(entry.outputs ?? null) } : { error: entry.error ?? null }),
    };
  });
}

// The container probe answers with its error object and the real failure
// document its Catch queried: a replay fixture for the whole Catch.
async function captureDocuments(client, sanitize, timeoutSeconds) {
  const stamp = new Date().toISOString().replace(/[-:T.Z]/g, "").slice(0, 14);
  const submitted = [];
  for (const s of PROBE_SCENARIOS) {
    const requestJson = JSON.stringify({ correlationId: s.id, data: s.data });
    submitted.push({ s, requestJson, id: await submitRequest(client, { key: PROBE_KEY, name: `doc-${s.id}-${stamp}`, requestJson }) });
  }
  const deadline = Date.now() + timeoutSeconds * 1000;
  return Promise.all(submitted.map(async ({ s, requestJson, id }) => {
    const { state, text } = await rawResponse(client, id, deadline);
    return { id: s.id, title: s.title, requestJson, state, response: sanitize(text) };
  }));
}

run(async ({ options }) => {
  const { client, config } = labClient();
  const capturedAt = new Date().toISOString();
  if (options.documents) {
    const cases = await captureDocuments(client, sanitizer(config), Number(options.timeout ?? 420));
    writeFileSync("tests/fixtures/expressions/catch-documents-live.json", `${JSON.stringify({ capturedAt, flow: "flows/probes/probe-containers.json", cases }, null, 2)}\n`);
    return { verdict: "CAPTURED", cases: cases.map((c) => `${c.id}:${c.state}`) };
  }
  const vectors = await captureVectors(client, Number(options.timeout ?? 300));
  writeFileSync("tests/fixtures/expressions/conformance-live.json", `${JSON.stringify({ capturedAt, flow: CONFORMANCE_FLOW, vectors }, null, 2)}\n`);
  const counts = vectors.reduce((acc, v) => ({ ...acc, [v.status]: (acc[v.status] ?? 0) + 1 }), {});
  return { verdict: "CAPTURED", total: vectors.length, counts };
});
