import process from "node:process";
import { loadLabConfig } from "./config.mjs";
import { createDataverseClient } from "./dataverse.mjs";

export function parseArgs(argv) {
  const positional = [];
  const options = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
